mapper.select:
SELECT sa.id, sa.stage_id, sa.approver_type, sa.approver_id, sa.check_secondary_dept, sa.sub_workflow_id, u.username, u.real_name, u.dept_id, u.role_id, r.name AS role_name, d.name AS dept_name, sub_w.name AS sub_workflow_name FROM stage_approver sa LEFT JOIN sys_user u ON sa.approver_type = 'USER' AND sa.approver_id = u.id AND u.deleted = 0 LEFT JOIN sys_role r ON (sa.approver_type = 'ROLE' AND sa.approver_id = r.id AND r.deleted = 0) OR (sa.approver_type = 'USER' AND u.role_id = r.id AND r.deleted = 0) LEFT JOIN sys_dept d ON (sa.approver_type = 'DEPT' AND sa.approver_id = d.id AND d.deleted = 0) OR (sa.approver_type = 'USER' AND u.dept_id = d.id AND d.deleted = 0) LEFT JOIN workflow sub_w ON sa.sub_workflow_id = sub_w.id AND sub_w.deleted = 0
AND sa.stage_id = #{stageId}
AND sa.stage_id IN
#{stageId}
AND sa.sub_workflow_id IS NULL AND sa.sub_workflow_id IS NOT NULL
ORDER BY sa.id ASC
